function Card({title,children,icon:Icon=Wallet}){return <article className="panel finance-card"><div className="panel-heading"><h2>{title}</h2><Icon size={19}/></div>{children}</article>}
function Stats({summary,display,onOpen}){const items=[['Recebido',summary.received,'income','confirmed'],['Pago',summary.paid,'paid','confirmed'],['A receber',summary.receivable,'income','scheduled'],['A pagar',summary.payable,'expense','scheduled'],['Saldo projetado',summary.projectedCash,'all','all']];return <section className="finance-stats decision-stats">{items.map(([label,value,type,status])=><button className="panel stat-action" key={label} onClick={()=>onOpen(type,status)}><span>{label}</span><strong className={label==='Pago'||label==='A pagar'||value<0?'negative':''}>{display(value)}</strong><small>Ver composição →</small></button>)}</section>}

export function FinanceDashboard({finance,month,display,onOpen}){const f=empty(finance),s=summarizeFinance(f,month);return <section className="finance-dashboard panel spaced"><div className="panel-heading"><div><h2>Seu mês financeiro</h2><p>Entradas, despesas e faturas; o saldo bancário fica fora do patrimônio investido.</p></div><button className="text-button" onClick={onOpen}>Abrir controle financeiro <ArrowUpRight size={16}/></button></div><div className="finance-summary-grid"><div><span>Disponível nas contas</span><strong>{display(s.cash)}</strong></div><div><span>Despesas do mês (cartão incluído)</span><strong>{display(s.expenses)}</strong></div><div><span>Faturas a vencer neste mês</span><strong>{display(s.due)}</strong></div></div></section>}

